    public NativeTrapdoorSettings settings(){return settings;}public NativeTrapdoorLinks links(){return links;}public boolean inert(){return inert;}public NativeTrapdoorVisual trapdoorVisual(){var state=publication;return state==null?null:state.visual();}public NativeTrapdoorGeometry.Snapshot geometry(){var state=publication;return state==null?null:state.geometry();}public net.minecraft.world.phys.shapes.VoxelShape collisionShape(){var state=publication;return state==null?net.minecraft.world.phys.shapes.Shapes.empty():state.collision();}
    public BlockPos position(){return worldPosition;}public boolean diagonal(){return settings.diagonal();}public boolean cover(){return settings.choices().cover;}public int geometryPosition(){return settings.choices().position;}public boolean sliding(){return settings.choices().sliding;}public int trigger(){return settings.choices().trigger;}
